:root {
  --bg: #2d1b4e;
  --card-bg: #f5f0e8;
  --primary: #6b4c9a;
  --accent: #e8a838;
  --text: #2d1b4e;
  --text-light: #f5f0e8;
  --border: #4a3670;
  --shadow: #1a0f2e;
  --focus: #e8a838;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--shadow) 25%, transparent 25%),
    linear-gradient(-45deg, var(--shadow) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--shadow) 75%),
    linear-gradient(-45deg, transparent 75%, var(--shadow) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  border-radius: 4px;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 20px;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  text-shadow: 2px 2px 0 var(--accent);
}

.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 16px;
}

.tab {
  flex: 1;
  padding: 12px 8px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  background: var(--border);
  color: var(--text-light);
  border: 3px solid var(--border);
  border-bottom: none;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  position: relative;
}

.tab:hover {
  background: var(--primary);
}

.tab:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  z-index: 1;
}

.tab:active {
  transform: translateY(2px);
}

.tab.active {
  background: var(--card-bg);
  color: var(--primary);
  border-bottom: 3px solid var(--card-bg);
  margin-bottom: -3px;
  z-index: 2;
}

.panels {
  border: 3px solid var(--border);
  background: var(--card-bg);
  padding: 16px;
}

.panel {
  display: none;
}

.panel.active {
  display: block;
}

textarea {
  width: 100%;
  min-height: 200px;
  padding: 12px;
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
  background: #fff;
  border: 3px solid var(--border);
  border-radius: 2px;
  resize: vertical;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(232, 168, 56, 0.3);
}

textarea::placeholder {
  color: #999;
}

.count {
  margin-top: 8px;
  font-size: 0.9rem;
  color: var(--primary);
  font-weight: 600;
  text-align: right;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .tab {
    font-size: 0.85rem;
    padding: 10px 4px;
  }
  textarea {
    min-height: 150px;
  }
}

(function () {
  'use strict';

  var tabs = Array.prototype.slice.call(document.querySelectorAll('[role="tab"]'));
  var panels = Array.prototype.slice.call(document.querySelectorAll('[role="tabpanel"]'));
  var textareas = Array.prototype.slice.call(document.querySelectorAll('textarea'));

  function activateTab(tab) {
    tabs.forEach(function (t) {
      var selected = t === tab;
      t.classList.toggle('active', selected);
      t.setAttribute('aria-selected', selected ? 'true' : 'false');
      t.setAttribute('tabindex', selected ? '0' : '-1');
    });

    panels.forEach(function (p) {
      var isActive = p.id === tab.getAttribute('aria-controls');
      p.classList.toggle('active', isActive);
      p.hidden = !isActive;
    });

    var panel = document.getElementById(tab.getAttribute('aria-controls'));
    if (panel) {
      var ta = panel.querySelector('textarea');
      if (ta) ta.focus();
    }
  }

  function updateCount(textarea) {
    var countId = textarea.getAttribute('aria-describedby');
    var countEl = document.getElementById(countId);
    if (countEl) {
      var len = textarea.value.length;
      countEl.textContent = len + (len === 1 ? ' character' : ' characters');
    }
  }

  tabs.forEach(function (tab, index) {
    tab.addEventListener('click', function () {
      activateTab(tab);
    });

    tab.addEventListener('keydown', function (e) {
      var newIndex = null;
      if (e.key === 'ArrowRight') {
        newIndex = (index + 1) % tabs.length;
      } else if (e.key === 'ArrowLeft') {
        newIndex = (index - 1 + tabs.length) % tabs.length;
      } else if (e.key === 'Home') {
        newIndex = 0;
      } else if (e.key === 'End') {
        newIndex = tabs.length - 1;
      } else if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        activateTab(tab);
        return;
      }
      if (newIndex !== null) {
        e.preventDefault();
        tabs[newIndex].focus();
        activateTab(tabs[newIndex]);
      }
    });
  });

  textareas.forEach(function (ta) {
    ta.addEventListener('input', function () {
      updateCount(ta);
    });
    updateCount(ta);
  });

  activateTab(tabs[0]);
})();
